do $$
declare s uuid:=gen_random_uuid();u uuid:=gen_random_uuid();foreign_store uuid:=gen_random_uuid();wh uuid;foreign_wh uuid;v integer;r jsonb;req uuid:=gen_random_uuid();fp text:=repeat('d',64);
begin
 insert into public.stores values(s),(foreign_store);insert into public.memberships values(s,u,'owner');insert into public.store_billing values(s,'sandbox','standard','ACTIVE',now()-interval '1 day',now()+interval '1 month');
 wh:=public.shipping_register_warehouse(s,'sandbox','SETTINGS-'||s::text);foreign_wh:=public.shipping_register_warehouse(foreign_store,'sandbox','SETTINGS-'||foreign_store::text);
 perform public.test_shipping_assert(not has_table_privilege('authenticated','private.shipping_settings','update'),'settings not raw writable');
 perform public.test_shipping_assert(not has_function_privilege('authenticated','public.shipping_settings_approve(uuid,uuid,integer,text)','execute'),'approval service only');
 perform public.test_shipping_reject(format('select public.shipping_settings_snapshot(%L,%L)',foreign_store,u));
 perform public.test_shipping_reject(format('select public.shipping_settings_save(%L,%L,0,%L,array[''2828''],''PICKUP_BY_DC'',5000,false)',s,u,wh));
 update public.store_billing set plan='premium' where store_id=s;
 v:=public.shipping_settings_save(s,u,0,wh,array['2828'],'PICKUP_BY_DC',5000,false);
 perform public.test_shipping_assert(v=1,'first draft version');
 r:=public.shipping_settings_snapshot(s,u);perform public.test_shipping_assert((r->'settings'->>'automatic_requested')::boolean=false,'automatic off by default');
 perform public.test_shipping_reject(format('select public.shipping_settings_save(%L,%L,0,%L,array[''2828''],''PICKUP_BY_DC'',5000,false)',s,u,wh));
 perform public.test_shipping_reject(format('select public.shipping_settings_save(%L,%L,1,%L,array[''2828''],''PICKUP_BY_DC'',5000,false)',s,u,foreign_wh));
 perform public.test_shipping_reject(format('select public.shipping_settings_save(%L,%L,1,%L,array[''2828'',''2828''],''PICKUP_BY_DC'',5000,false)',s,u,wh));
 v:=public.shipping_settings_save(s,u,1,wh,array['2828','56468'],'PICKUP_BY_DC',5000,true);
 perform public.test_shipping_reject(format('select public.shipping_settings_approve(%L,%L,2,%L)',s,u,fp));
 insert into public.policy_versions(store_id) values(s);
 v:=public.shipping_settings_approve(s,u,2,fp);perform public.test_shipping_assert(v=3,'approved increment');
 perform public.test_shipping_assert(public.shipping_settings_approve(s,u,3,fp)=3,'approval replay');
 insert into public.policy_versions(store_id,published_at) values(s,now()+interval '1 second');
 perform public.test_shipping_assert((public.shipping_settings_snapshot(s,u)->>'policyChanged')::boolean,'new policy needs approval');
 v:=public.shipping_settings_approve(s,u,3,fp);perform public.test_shipping_assert(v=4,'policy reapproval');
 update public.store_billing set period_end=now()-interval '1 day' where store_id=s;
 perform public.test_shipping_reject(format('select public.shipping_settings_save(%L,%L,4,%L,array[''2828''],''PICKUP_BY_DC'',5000,false)',s,u,wh));
 v:=public.shipping_settings_pause(s,u,4);perform public.test_shipping_assert(v=5,'pause after expiry');
 perform public.test_shipping_assert(public.shipping_settings_pause(s,u,5)=5,'pause replay');
 perform public.test_shipping_assert((select count(*) from private.shipping_settings_events where store_id=s)=5,'settings history');
 update public.store_billing set period_end=now()+interval '1 month' where store_id=s;
 perform public.test_shipping_assert(public.shipping_settings_warehouse_start(req,s,u,fp),'warehouse create claim');
 perform public.test_shipping_assert(not public.shipping_settings_warehouse_start(req,s,u,fp),'no duplicate create');
 perform public.test_shipping_reject(format('select public.shipping_settings_warehouse_start(%L,%L,%L,%L)',gen_random_uuid(),s,u,fp));
 perform public.shipping_settings_warehouse_finish(req,s,u,fp,false);
 perform public.test_shipping_assert((public.shipping_settings_snapshot(s,u)->'pendingWarehouse'->>'state')='UNKNOWN','unknown creation preserved');
 perform public.test_shipping_reject(format('select public.shipping_settings_warehouse_finish(%L,%L,%L,%L,true)',req,s,u,repeat('e',64)));
 wh:=public.shipping_settings_warehouse_finish(req,s,u,fp,true);
 perform public.test_shipping_assert(wh=public.shipping_settings_warehouse_finish(req,s,u,fp,true),'verification replay');
 perform public.test_shipping_assert(public.shipping_settings_snapshot(s,u)->'pendingWarehouse'='null'::jsonb,'pending cleared by verified match');
 update public.memberships set role='viewer' where store_id=s and user_id=u;
 perform public.test_shipping_assert(not (public.shipping_settings_snapshot(s,u)->>'canManage')::boolean,'read only member');
 perform public.test_shipping_reject(format('select public.shipping_settings_pause(%L,%L,5)',s,u));
end $$;
